css:
:root, :root.dark {
  --bg: #0a0a12;
  --surface: #12121f;
  --border: #2b2b45;
  --text: #e0f7ff;
  --text-medium: #9adfff;
  --text-muted: #6f9fb8;
  --text-ghost: #46688a;
}
body { background: linear-gradient(180deg, #0a0a12 0%, #101024 100%); }
.card-tile { border: 1px solid #ff2bd6; border-radius: 4px; box-shadow: 0 0 8px rgba(255, 43, 214, 0.35); }
.card-tile:hover { border-color: #00e5ff; box-shadow: 0 0 14px rgba(0, 229, 255, 0.6); }
.card-tag { background: #ff2bd6; color: #0a0a12; }
.header { border-bottom: 1px solid #00e5ff; }
button:focus { outline-color: #00e5ff; }
